query:
SELECT Id, Name, Type, RootPath, GitUrl, GitBranch
FROM dbo.repositories
ORDER BY Name;

SELECT
    CONVERT(varchar(64), HASHBYTES('SHA2_256', CONVERT(varbinary(max), OBJECT_DEFINITION(OBJECT_ID('[CNS_CPO_MID_CAPACITY].[BALANCE_TIMETRAVEL_UPSTREAM_PRODUCTION_VW]')))), 2) AS definition_hash,
    LEN(OBJECT_DEFINITION(OBJECT_ID('[CNS_CPO_MID_CAPACITY].[BALANCE_TIMETRAVEL_UPSTREAM_PRODUCTION_VW]'))) AS definition_length;

